def minPath(grid, k):
    n = len(grid)

    # Find position of value 1
    start = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start:
            break

    path = [1]
    r, c = start

    for _ in range(k - 1):
        min_val = float('inf')
        best = None
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] < min_val:
                    min_val = grid[nr][nc]
                    best = (nr, nc)
        path.append(min_val)
        r, c = best

    return path
